"""Part 3: regenerate a self-contained HTML dashboard from the output JSON files only (plan Part 3).
No number in the report is typed by hand. Usage: python code/04_build_report.py"""
from pathlib import Path
import json, datetime
ROOT = Path(__file__).resolve().parents[1]; OUT = ROOT / "out"
p1 = json.load(open(OUT / "part1_overall.json"))
p2 = json.load(open(OUT / "part2_segments.json"))
rr = OUT / "part2_segments_rerun.json"
if rr.exists():
    p2.update(json.load(open(rr)))
summ = json.load(open(OUT / "part2_summary.json"))
data = {"p1": p1, "p2": p2, "summary": summ,
        "plan_hash": (ROOT / "logs" / "plan_hash.txt").read_text().split()[0],
        "built": datetime.datetime.now().strftime("%Y-%m-%d %H:%M")}

HTML = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Criteo Bayesian Readout</title>
<style>
:root{--bg:#fbfbfa;--card:#fff;--ink:#1d1d1b;--ink2:#5b5b57;--muted:#8a8a85;--grid:#e6e5e1;--line:#d6d5d0;
--s1:#2f6db5;--s2:#c8641e;--s0:#55554f}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#161615;--card:#1f1f1d;--ink:#ecebe7;--ink2:#b3b2ad;--muted:#85847f;--grid:#2e2e2b;--line:#3a3a37;--s1:#6ea3e6;--s2:#e8935a;--s0:#a9a8a2}}
:root[data-theme="dark"]{--bg:#161615;--card:#1f1f1d;--ink:#ecebe7;--ink2:#b3b2ad;--muted:#85847f;--grid:#2e2e2b;--line:#3a3a37;--s1:#6ea3e6;--s2:#e8935a;--s0:#a9a8a2}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}
main{max-width:1080px;margin:0 auto;padding:24px 16px 48px}h1{font-size:22px;margin:0 0 4px}h2{font-size:16px;margin:28px 0 10px}
.sub{color:var(--ink2);margin:0 0 18px}.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.tile{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px}.tile .k{color:var(--ink2);font-size:12px}
.tile .v{font-size:24px;font-weight:600;margin:4px 0}.tile .d{color:var(--muted);font-size:12px}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px;overflow-x:auto}
table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}th,td{padding:6px 8px;border-bottom:1px solid var(--grid);text-align:right}
th:first-child,td:first-child{text-align:left}th{color:var(--ink2);font-weight:500}
.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:8px}select{font:inherit;padding:4px 6px}
.legend{display:flex;gap:14px;flex-wrap:wrap;color:var(--ink2);font-size:12px}.sw{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:5px;vertical-align:-1px}
#tip{position:fixed;pointer-events:none;background:var(--card);border:1px solid var(--line);border-radius:6px;padding:6px 8px;font-size:12px;display:none;box-shadow:0 2px 8px rgba(0,0,0,.12)}
.note{color:var(--muted);font-size:12px;margin-top:8px}svg text{fill:var(--ink2);font-size:11px}
</style></head><body><main>
<h1>Criteo advertising experiment: Bayesian readout</h1>
<p class="sub">Public Criteo Uplift v2.1 data from an experiment Criteo randomized and completed. Generated by <code>code/04_build_report.py</code> from output files; plan SHA-256 <span id="hash"></span>; built <span id="built"></span>.</p>
<div class="tiles" id="tiles"></div>
<h2>Segment effects from a 2% sample (100 segments)</h2>
<div class="card"><div class="controls"><label>Replicate <select id="rep"></select></label>
<div class="legend"><span><span class="sw" style="background:var(--s0)"></span>Benchmark (other 98% of users)</span><span><span class="sw" style="background:var(--s2)"></span>No pooling</span><span><span class="sw" style="background:var(--s1)"></span>Multilevel model, 90% interval</span></div></div>
<svg id="seg" width="100%" viewBox="0 0 1000 340" role="img" aria-label="Segment effects"></svg>
<p class="note">Segments sorted by benchmark effect. Absolute lift is not a population effect: the dataset is subsampled non-uniformly.</p></div>
<h2>Accuracy by replicate (visit lift, percentage points)</h2>
<div class="card"><table id="reps"></table><p class="note" id="decision"></p></div>
</main><div id="tip"></div>
<script>
const D=__DATA__;const pp=x=>(100*x).toFixed(2);
document.getElementById('hash').textContent=D.plan_hash.slice(0,12)+'…';document.getElementById('built').textContent=D.built;
const v=D.p1.visit,c=D.p1.conversion,S=D.summary;
const tiles=[["Users",D.p1.n_users.toLocaleString(),"85% assigned to ads"],
["Visit lift (posterior mean)",pp(v.bayes_lift_mean)+" pp","95% CrI "+pp(v.bayes_lift_ci95[0])+" to "+pp(v.bayes_lift_ci95[1])+"; P(lift>0) = "+v.p_lift_gt_0.toFixed(3)],
["Conversion lift",pp(c.bayes_lift_mean)+" pp","relative +"+(100*c.bayes_rel_mean).toFixed(0)+"% on "+(100*c.rate0).toFixed(3)+"%"],
["Segment RMSE, multilevel vs no pooling",pp(S.mean_rmse.bayes)+" vs "+pp(S.mean_rmse.nopool)+" pp","lower in "+S.bayes_better_count+" of "+S.n_reps+" replicates"]];
document.getElementById('tiles').innerHTML=tiles.map(t=>`<div class="tile"><div class="k">${t[0]}</div><div class="v">${t[1]}</div><div class="d">${t[2]}</div></div>`).join('');
const reps=Object.keys(D.p2).sort((a,b)=>a-b);const sel=document.getElementById('rep');
sel.innerHTML=reps.map(r=>`<option value="${r}">${+r+1}</option>`).join('');
const tip=document.getElementById('tip');
function draw(r){const g=D.p2[r].seg,n=g.bench.length,ord=[...Array(n).keys()].sort((a,b)=>g.bench[a]-g.bench[b]);
const all=[].concat(g.np_lo,g.np_hi,g.lo,g.hi,g.bench);let lo=Math.min(...g.lo,...g.bench,...g.nopool),hi=Math.max(...g.hi,...g.bench,...g.nopool);
const pad=(hi-lo)*.05;lo-=pad;hi+=pad;const L=56,R=990,T=10,B=310,X=i=>L+(R-L)*(i+.5)/n,Y=y=>B-(B-T)*(y-lo)/(hi-lo);
let s='';const step=Math.pow(10,Math.floor(Math.log10((hi-lo)/4)));const st=Math.ceil(((hi-lo)/5)/step)*step;
for(let t=Math.ceil(lo/st)*st;t<=hi;t+=st){s+=`<line x1="${L}" x2="${R}" y1="${Y(t)}" y2="${Y(t)}" stroke="var(--grid)"/><text x="${L-6}" y="${Y(t)+4}" text-anchor="end">${pp(t)}</text>`}
s+=`<line x1="${L}" x2="${R}" y1="${Y(0)}" y2="${Y(0)}" stroke="var(--muted)"/><text x="${(L+R)/2}" y="332" text-anchor="middle">Segments (sorted by benchmark effect)</text>`;
ord.forEach((k,i)=>{const x=X(i);s+=`<line x1="${x+2}" x2="${x+2}" y1="${Y(g.lo[k])}" y2="${Y(g.hi[k])}" stroke="var(--s1)" stroke-width="2" stroke-linecap="round" opacity=".55"/>`;
s+=`<circle cx="${x-2}" cy="${Y(g.nopool[k])}" r="3" fill="var(--s2)" stroke="var(--card)" stroke-width="1.5"/>`;
s+=`<circle cx="${x+2}" cy="${Y(g.bayes[k])}" r="3" fill="var(--s1)" stroke="var(--card)" stroke-width="1.5"/>`;
s+=`<circle cx="${x}" cy="${Y(g.bench[k])}" r="3" fill="var(--s0)" stroke="var(--card)" stroke-width="1.5"/>`;
s+=`<rect x="${x-5}" y="${T}" width="10" height="${B-T}" fill="transparent" data-k="${k}"/>`});
const svg=document.getElementById('seg');svg.innerHTML=s;
svg.querySelectorAll('rect[data-k]').forEach(el=>{el.onmousemove=e=>{const k=+el.dataset.k;tip.style.display='block';tip.style.left=(e.clientX+12)+'px';tip.style.top=(e.clientY+12)+'px';
tip.innerHTML=`Segment ${k+1}<br>Benchmark ${pp(g.bench[k])} pp<br>No pooling ${pp(g.nopool[k])} pp<br>Multilevel ${pp(g.bayes[k])} pp (${pp(g.lo[k])} to ${pp(g.hi[k])})`};el.onmouseleave=()=>tip.style.display='none'})}
sel.onchange=()=>draw(sel.value);draw(reps[0]);
const rows=reps.map(r=>{const o=D.p2[r];return `<tr><td>${+r+1}</td><td>${o.n_users.toLocaleString()}</td><td>${pp(o.rmse.nopool)}</td><td>${pp(o.rmse.cpool)}</td><td>${pp(o.rmse.bayes)}</td><td>${pp(o.top20_bench_mean.nopool)}</td><td>${pp(o.top20_bench_mean.bayes)}</td><td>${(100*o.coverage90.bayes).toFixed(0)}%</td><td>${o.rhat_max.toFixed(3)}</td></tr>`}).join('');
document.getElementById('reps').innerHTML=`<tr><th>Replicate</th><th>Users</th><th>RMSE no pooling</th><th>RMSE complete pooling</th><th>RMSE multilevel</th><th>Top-20 picks, no pooling</th><th>Top-20 picks, multilevel</th><th>90% coverage, multilevel</th><th>Max R-hat</th></tr>`+rows;
document.getElementById('decision').textContent=`Pre-specified rule: multilevel helps if RMSE is lower than no pooling in at least 8 of 10 replicates and the mean paired difference has a 95% interval below zero. Result: ${S.bayes_better_count} of ${S.n_reps}; mean difference ${pp(S.diff_mean)} pp (95% CI ${pp(S.diff_ci95[0])} to ${pp(S.diff_ci95[1])}): ${S.rule_met?'met':'not met'}. Top-20 picks report the benchmark effect of the 20 segments each method ranks highest (all-segment mean ${pp(S.top20.all)} pp).`;
</script></body></html>"""
(OUT / "criteo_bayes_report.html").write_text(HTML.replace("__DATA__", json.dumps(data)), encoding="utf-8")
print("wrote", OUT / "criteo_bayes_report.html")
